type ChromeLinkPolicy struct { fetchable datahelpers.PageURLSet; unfiltered bool }

func LoadChromeLinkPolicy(ctx context.Context, db *sql.DB, siteID uuid.UUID, logger *zap.Logger) ChromeLinkPolicy {
	fetchable, deployedPages, err := loadFetchablePageSet(ctx, db, siteID)
	switch {
	case err != nil:
		logger.Warn("ChromeLinkPolicy: fetchable-page lookup failed; chrome links go UNFILTERED rather than risk empty chrome", zap.String("site_id", siteID.String()), zap.Error(err))
		return ChromeLinkPolicy{unfiltered: true}
	case deployedPages == 0:
		// first build: "never deployed" is true of everything and carries no signal.
		logger.Warn("ChromeLinkPolicy: site has NO deployed pages — chrome links go UNFILTERED (expected during a first build, anomalous on an established site)", zap.String("site_id", siteID.String()))
		return ChromeLinkPolicy{unfiltered: true}
	}
	return ChromeLinkPolicy{fetchable: fetchable}
}

func (p ChromeLinkPolicy) Unfiltered() bool { return p.unfiltered }

func (p ChromeLinkPolicy) Allows(href string) bool {
	if p.unfiltered { return true }
	if datahelpers.ClassifyLinkScope(href) != datahelpers.LinkScopePage { return true }
	return p.fetchable.Contains(href)
}

